messages.content:
{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": [
      {
        "ref": "L01",
        "text": "(守邴原别傳曰原字根矩東管朱虚人少孤數嵗/魏書曰度字叔濟襄平人累遷冀州刺史遼東太)"
      },
      {
        "ref": "L02",
        "text": "(有親也一則願其不孤二則羨其得學中心感傷故/時過書舍而泣師問曰童子何泣也原曰凢得學者)"
      },
      {
        "ref": "L03",
        "text": "(覽洽聞金玉其行知世將亂避地遼東公孫度厚禮/泣耳師惻然曰苟欲學不須資也於是就業長則博)"
      },
      {
        "ref": "L04",
        "text": "(落曰移北近郡以觀其意皆曰樂移原舊有捕魚大/之中國既寧欲還鄉里爲度禁絶原宻自治嚴謂部)"
      },
      {
        "ref": "L05",
        "text": "(之度曰邴君所謂雲中白鶴非鶉鷃之網所能羅也/船請村落皆令熟醉因夜去之數日度乃覺吏欲追)"
      },
      {
        "ref": "L06",
        "text": "(五官中郎長史/魏王辟祭酒累遷)"
      }
    ]
  },
  "frozen_questions": [
    {
      "gap": "这段行动或处境为何影响正文理解？",
      "question_id": "Q1",
      "story_span": "公孫度目邴原所謂雲中白鶴非燕雀之網所"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": [
      {
        "layer": "collation_note",
        "ref": "J01",
        "source_labels": [],
        "speaker": null,
        "text": "注「移比近郡」「比」，景宋本作「北」。"
      },
      {
        "layer": "jianshu_note",
        "ref": "J02",
        "source_labels": [],
        "speaker": "程炎震",
        "text": "〔一〕 程炎震云：「管當作莞，魏志邴原傳曰：『北海朱虛人。』按北海漢郡，東莞建安中所立。」"
      },
      {
        "layer": "jianshu_note",
        "ref": "J03",
        "source_labels": [
          "別傳"
        ],
        "speaker": "程炎震",
        "text": "〔二〕 程炎震云：「魏志注引別傳曰：『辟東閤祭酒。』」"
      }
    ]
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "公孫度目邴原所謂雲中白鶴非燕雀之網所能羅\n也"
  },
  "story_id": "08-shangyu-004"
}
